tool_input.command:
python3 - <<'EOF'
p = "src/inventory/repository.py"
s = open(p).read()
s = s.replace(
    "from .errors import DuplicateEntity, OrderNotFound, UnknownSku, UnknownWarehouse\n"
    "from .models import Order, OrderStatus, Product, Warehouse\n",
    "from .errors import (\n    DuplicateEntity,\n    OrderNotFound,\n    ReservationNotFound,\n    UnknownSku,\n    UnknownWarehouse,\n)\n"
    "from .models import Order, OrderStatus, Product, Reservation, ReservationStatus, Warehouse\n",
)
s = s.replace(
    "        self._order_seq = 0\n",
    "        self._order_seq = 0\n"
    "        self._reservations: dict[str, Reservation] = {}\n"
    "        self._reservation_seq = 0\n"
    "        # idempotency key -> (warehouse, requested items, reservation id)\n"
    "        self._reservation_keys: dict[str, tuple[str, dict[str, int], str]] = {}\n",
)
s += '''
    # -- reservations ----------------------------------------------------
    def next_reservation_id(self) -> str:
        self._reservation_seq += 1
        return f"RES-{self._reservation_seq:04d}"

    def save_reservation(self, reservation: Reservation) -> None:
        self._reservations[reservation.reservation_id] = reservation

    def get_reservation(self, reservation_id: str) -> Reservation:
        try:
            return self._reservations[reservation_id]
        except KeyError:
            raise ReservationNotFound(reservation_id) from None

    def reservations(
        self, warehouse: str | None = None, status: ReservationStatus | None = None
    ) -> list[Reservation]:
        return [
            r
            for r in self._reservations.values()
            if (warehouse is None or r.warehouse == warehouse)
            and (status is None or r.status is status)
        ]

    def remember_reservation_key(
        self, key: str, warehouse: str, requested: dict[str, int], reservation_id: str
    ) -> None:
        self._reservation_keys[key] = (warehouse, dict(requested), reservation_id)

    def reservation_key(self, key: str) -> tuple[str, dict[str, int], str] | None:
        """The request first seen under ``key``, or None if the key is new."""
        return self._reservation_keys.get(key)
'''
open(p, "w").write(s)
EOF
